const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',accounts:'M3 6h18v14H3z M3 10h18 M16 15h2 M6 3h12',analysts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',risk:'M12 22s9-4 9-11V5l-9-3-9 3v6c0 7 9 11 9 11z M8 12l3 3 5-6',trades:'M3 17l6-6 4 4 8-11 M15 4h6v6 M3 21h18',activity:'M3 12h4l3-8 4 16 3-8h4',billing:'M3 5h18v14H3z M3 9h18 M7 15h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 3-3 1-1 3H9l-1-3-3-1-2-5 2-3 3-1z',arrow:'M5 12h14 M13 6l6 6-6 6',plus:'M12 5v14 M5 12h14',chevron:'M8 5l7 7-7 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',pause:'M8 5v14 M16 5v14',play:'M7 4l14 8-14 8z',logout:'M9 4H4v16h5 M9 12h12 M16 7l5 5-5 5',close:'M6 6l12 12 M6 18 18 6',check:'M4 12l5 5L20 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',menu:'M3 6h18 M3 12h18 M3 18h18',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',alert:'M12 3 2 21h20L12 3z M12 9v5 M12 17v1',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 6 M18 17a7 7 0 0 1-12 1l-2-6',wallet:'M3 6h16v14H3z M3 6V3h14v3 M15 11h6v5h-6z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.overview}"/></svg>`;
const brand=()=>`<a class="brand" href="${current&&!publicDemo?'#overview':'#login'}"><img src="/assets/mark.svg" alt=""><span>Gold Copier<small>Community execution</small></span></a>`;
let publicDemo=false,current=null,csrf='',config={},data=null,selected=localStorage.getItem('gold-account'),activePage='overview',toastTimer,operator=null,chartPeriod='7D';
const fmt=(n,d=2)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=(n,c='USD')=>`${esc(c)} ${fmt(n)}`;
const when=t=>t?new Date(t*1000).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not connected';
const relative=t=>!t?'—':Date.now()/1000-t<60?'Just now':Date.now()/1000-t<3600?`${Math.floor((Date.now()/1000-t)/60)}m ago`:when(t);
const initials=n=>String(n||'GC').split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();
const badge=(text,kind='')=>`<span class="badge ${kind}"><span class="dot"></span>${esc(text)}</span>`;
const button=(label,action,ico='',cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const account=()=>data?.accounts.find(a=>a.id===selected)||data?.accounts[0];
const empty=(title,text,action='',label='')=>`<div class="empty">${icon('link')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action?button(label,action,'plus','primary'):''}</div>`;
function hideToast(){clearTimeout(toastTimer);$('#toast').className=''}
function placeToast(){const t=$('#toast'),d=$('#modal');(d.open?d:document.body).append(t)}
function clearSession(){publicDemo=false;current=null;csrf='';data=null;operator=null;selected=null;localStorage.removeItem('gold-account');$('#modal').close();placeToast();$('#modal').replaceChildren()}
function toast(message,error=false){placeToast();const t=$('#toast');t.innerHTML=`<span>${esc(message)}</span><button type="button" data-action="dismiss-toast" aria-label="Dismiss notification">${icon('close')}</button>`;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,5500)}
async function api(path,options={}){if(publicDemo&&options.method&&options.method!=='GET'&&!path.startsWith('/auth/'))throw Error('This public demo is read-only. Sign in to change workspace settings.');const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});let body;try{body=await response.json()}catch{body={detail:await Promise.resolve('Request failed')}}if(!response.ok){if(response.status===401&&current){clearSession();location.hash='login';await route()}let msg=body.detail;if(Array.isArray(msg))msg=msg.map(e=>`${e.loc.at(-1)}: ${e.msg}`).join('; ');const error=Error(msg||'Request failed');error.status=response.status;throw error}return body}
const post=(path,body={})=>api(path,{method:'POST',body});
function fieldsNumber(label,name,value,help='',step='.1',min='0',max=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="number" value="${esc(value)}" step="${step}" min="${min}" ${max?`max="${max}"`:''} required>${help?`<small>${help}</small>`:''}</div>`}
function modal(title,body,formId=null,submitLabel='Save changes'){const d=$('#modal');document.body.append($('#toast'));d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="btn ghost small" data-action="dismiss" aria-label="Close dialog">${icon('close')}</button></div>${formId?`<form id="${formId}">`:''}<div class="modal-body">${body}</div>${formId?`<div class="form-actions"><button type="button" class="btn" data-action="dismiss">Cancel</button><button class="btn primary" type="submit">${submitLabel}</button></div></form>`:''}`;if(!d.open)d.showModal();placeToast()}
function landing(){return `<div class="landing"><header>${brand()}<nav><a href="#how">How it works</a><a href="#login">Sign in</a><a class="btn primary" href="#signup">Get started ${icon('arrow')}</a></nav></header><section class="hero"><div><div class="eyebrow">ONE COMMUNITY. A CONNECTED WORKSPACE.</div><h1>Your trader’s edge.<br><em>In perfect sync.</em></h1><p>Bring your community’s gold signals into one clear workspace. Connect MT5, set your own risk, and stay in control of every trade.</p><div class="actions"><a class="btn primary" href="#signup">Create your workspace ${icon('arrow')}</a><a class="btn" href="${config.demo?'#demo':'#how'}">${config.demo?'Explore live demo':'Explore how it works'}</a></div><small>XAUUSD focused &nbsp;·&nbsp; Individual account controls &nbsp;·&nbsp; MT5 native</small></div><div class="hero-visual"><div class="eyebrow">A CALMER WAY TO FOLLOW THE MARKET</div><h2>From signal to execution.</h2><svg class="chart" viewBox="0 0 420 140" fill="none"><path d="M0 120H420 M0 70H420 M0 20H420" stroke="#32484a"/><path d="M0 111 30 99 60 105 90 77 120 85 150 49 180 60 210 45 240 61 270 29 300 39 330 19 360 29 390 9 420 17" stroke="#dcb874" stroke-width="2.5"/></svg><div class="hero-order">${icon('risk')}<div><p>Your account. Your parameters.</p><small>Entry · stop loss · targets · breakeven</small></div>${badge('MT5')}</div><small class="muted">Illustrative graphic. No investment performance is represented.</small></div></section><section class="feature-grid" id="how"><article>${icon('accounts')}<h3>Connect your MT5</h3><p>Link a dedicated account through your own Windows worker, or through an operator-configured managed terminal pool.</p></article><article>${icon('risk')}<h3>Define your boundaries</h3><p>Choose percentage, cash, or fixed-lot sizing. Add daily loss limits, drawdown protection, and entry filters.</p></article><article>${icon('activity')}<h3>Follow with visibility</h3><p>See account status, trade commands, execution results, and the activity behind every signal.</p></article></section><p class="landing-note">${config.demo?'This installation is a demonstration workspace. Broker execution is disabled.':'Live execution requires operator enablement and independently verified MT5 deployment.'} Trading involves risk. Stops and risk settings do not guarantee a maximum loss.</p><footer class="landing-footer">Gold Copier · Independent community execution software &nbsp; / &nbsp; <a href="#legal">Service & privacy information</a></footer></div>`}
function authPage(mode){const signup=mode==='signup',forgot=mode==='forgot',reset=mode==='reset';return `<main class="auth-page"><aside class="auth-art">${brand()}<div class="auth-copy"><div class="eyebrow">LESS FRICTION. MORE CONTROL.</div><h1>One signal.<br>Your own rules.</h1><p>A considered workspace for your community’s trades, your accounts, and the risk you choose to take.</p></div><small>Gold Copier · XAUUSD community execution</small></aside><section class="auth-form"><div class="auth-card"><div class="eyebrow">YOUR TRADING WORKSPACE</div><h1>${signup?'Create your account':forgot?'Reset your password':reset?'Choose a new password':'Welcome back.'}</h1><p>${signup?'Set up your workspace. Connect an MT5 account when you’re ready.':forgot?'We’ll email a reset link if an account exists.':reset?'Use at least 12 characters. Existing sessions will be signed out.':'Sign in to keep everything in sync.'}</p><form id="${signup?'signup-form':forgot?'forgot-form':reset?'reset-form':'login-form'}">${signup?'<div class="field"><label for="name">Full name</label><input id="name" name="name" autocomplete="name" minlength="2" maxlength="80" required placeholder="Your name"></div>':''}${!reset?'<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></div>':''}${!forgot?`<div class="field"><label for="password">Password</label><div class="password-control"><input id="password" name="password" type="password" autocomplete="${signup||reset?'new-password':'current-password'}" minlength="12" maxlength="128" required placeholder="At least 12 characters"><button type="button" class="password-toggle" data-action="toggle-password" aria-controls="password" aria-label="Show password" aria-pressed="false"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div>`:''}${!signup&&!forgot&&!reset?'<a class="muted" href="#forgot">Forgot your password?</a>':''}<div id="auth-error" class="form-error" hidden></div><button class="btn primary" type="submit">${signup?'Create account':forgot?'Send reset link':reset?'Reset password':'Sign in'} ${icon('arrow')}</button></form><p class="sub">${signup?'Already have an account? <a href="#login">Sign in</a>':'New to Gold Copier? <a href="#signup">Create an account</a>'}</p>${config.demo?'<p class="section-note">Demo environment. Use the credentials supplied by your operator. No real orders can be sent from this workspace.</p>':''}<a class="back" href="#home">← Back to overview</a></div></section></main>`}
function chart(){const a=account();let points=(data.equity||[]).filter(p=>p.account_id===a?.id);const cutoff=Date.now()/1000-({ '1D':86400,'7D':604800,'30D':2592000}[chartPeriod]);points=points.filter(p=>p.created>=cutoff);if(points.length<2)return empty('Your equity curve starts here','Verified worker snapshots will appear after your terminal connects.');const vals=points.map(p=>p.equity),lo=Math.min(...vals),hi=Math.max(...vals),range=hi-lo||1;const path=vals.map((v,i)=>`${i?'L':'M'}${(i/(vals.length-1)*700).toFixed(1)},${(155-(v-lo)/range*130).toFixed(1)}`).join(' ');return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 700 180" preserveAspectRatio="none" role="img" aria-label="Equity snapshots for selected account"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#7fa990" stop-opacity=".24"/><stop offset="100%" stop-color="#7fa990" stop-opacity="0"/></linearGradient></defs><path d="M0 25H700 M0 70H700 M0 115H700 M0 160H700" stroke="#ecf0ed" stroke-dasharray="4 5"/><path d="${path} L700 180 L0 180 Z" fill="url(#chartFill)"/><path d="${path}" fill="none" stroke="#58866e" stroke-width="2.4" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels"><span>${esc(when(points[0].created))}</span><span>Account equity · ${esc(a.snapshot.currency||'USD')}</span><span>${esc(when(points.at(-1).created))}</span></div></div>`}
function accountSelect(){return data.accounts.length?`<select class="select mobile-select" id="account-select" aria-label="Selected MT5 account">${data.accounts.map(a=>`<option value="${a.id}" ${a.id===account()?.id?'selected':''}>${esc(a.name)} · ${esc(a.login)}</option>`).join('')}</select>`:button('Connect account','connect','plus')}
function positionsTable(limit=50){const a=account(),positions=(a?.snapshot.positions||[]).slice(0,limit);if(!positions.length)return empty('No open positions','Positions appear after your worker verifies them with the broker.');return `<div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Side / volume</th><th>Entry</th><th>SL / TP</th><th>Floating P&L</th><th>Manage</th></tr></thead><tbody>${positions.map(p=>`<tr><td><div class="symbol"><span class="symbol-mark">Au</span><div><strong>${esc(p.symbol)}</strong><small>#${esc(p.ticket)}</small></div></div></td><td>${badge(p.side,p.side==='BUY'?'':'red')} <small>${fmt(p.volume)} lots</small></td><td>${fmt(p.price_open)}</td><td>${p.sl?fmt(p.sl):'—'} / ${p.tp?fmt(p.tp):'Runner'}</td><td class="${p.profit>=0?'positive':'negative'}">${p.profit>=0?'+':''}${fmt(p.profit)}</td><td>${p.copier?button('Manage','manage','settings','small',`data-ticket="${esc(p.ticket)}"`):'<small>External trade</small>'}</td></tr>`).join('')}</tbody></table></div>`}
function recentEvents(limit=4){return data.events.length?data.events.slice(0,limit).map(e=>`<div class="feed-item"><span class="feed-icon">${icon(e.kind==='risk'?'risk':e.kind==='execution'?'check':e.kind==='alert'?'alert':'activity')}</span><div class="feed-text"><p>${esc(e.detail)}</p><small>${esc(e.kind.replaceAll('_',' '))}</small></div><time>${relative(e.created)}</time></div>`).join(''):empty('All quiet for now','Connection, signal, and execution events will appear here.')}
function overview(){const a=account(),s=a?.snapshot||{},cur=s.currency||'USD',positions=s.positions||[],risk=a?.risk;return `<div class="page-title"><div><div class="eyebrow">YOUR WORKSPACE AT A GLANCE</div><h1>Good to have you here, ${esc(current.name.split(' ')[0])}.</h1><p>Your community, your accounts, your control.</p></div><div class="actions">${accountSelect()}${button('Refresh','refresh','refresh')}</div></div>${config.demo?'<div class="banner">'+icon('alert')+'<span>Demo workspace · All balances, trades, and chart data are seeded examples. Broker execution is disabled.</span><a href="#settings">Environment details</a></div>':data.paused?'<div class="banner">'+icon('pause')+'<span>The operator has paused new entries. Existing trade protection remains active.</span></div>':''}<section class="stats"><article class="stat"><div class="stat-head">Account equity ${icon('wallet')}</div><div class="stat-value">${a?fmt(s.equity):'—'} <small>${esc(cur)}</small></div><div class="stat-bottom">${s.balance!==undefined?`Balance ${fmt(s.balance)} ${esc(cur)}`:'Awaiting broker verification'}</div></article><article class="stat"><div class="stat-head">Today’s realized P&L ${icon('trades')}</div><div class="stat-value ${s.daily_pnl>=0?'positive':'negative'}">${s.daily_pnl!==undefined?(s.daily_pnl>=0?'+':'')+fmt(s.daily_pnl):'—'}</div><div class="stat-bottom">Broker history · account currency</div></article><article class="stat"><div class="stat-head">Open positions ${icon('activity')}</div><div class="stat-value">${positions.length.toString().padStart(2,'0')}</div><div class="stat-bottom">${(s.orders||[]).length} pending orders <span>·</span> ${risk?.max_open||0} position limit</div></article><article class="stat"><div class="stat-head">Execution status ${icon('risk')}</div><div class="stat-value">${config.demo?'Demo':a?.enabled&&a.online?'Active':a?.online?'Paused':'Offline'}</div><div class="stat-bottom">${config.demo?'Simulation environment':a?.heartbeat?'Last heartbeat '+relative(a.heartbeat):'Connect your MT5 worker'}</div></article></section><section class="grid-main"><article class="panel"><div class="panel-head"><h2>Account performance</h2><div class="tabs">${['1D','7D','30D'].map(t=>`<button class="${chartPeriod===t?'active':''}" data-action="chart-period" data-period="${t}">${t}</button>`).join('')}</div></div><div class="chart-top"><div><small>Equity history</small><div class="chart-total">${a?money(s.equity,cur):'—'}</div></div>${badge(config.demo?'Sample data':'Worker snapshots',config.demo?'demo':'gray')}</div>${chart()}</article><aside class="panel"><div class="panel-head"><h2>Connected account</h2><a href="#accounts">${icon('chevron')}</a></div><div class="panel-body">${a?`<div class="account-overview"><span class="broker-mark">${esc(a.broker[0])}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.broker)} · MT5</small></div></div><div class="account-details"><div class="detail"><span>Account</span><strong>${esc(a.login)}</strong></div><div class="detail"><span>Server</span><strong>${esc(a.server)}</strong></div><div class="detail"><span>Account type</span>${badge(a.mode==='live'?'Live':'Demo',a.mode==='live'?'':'demo')}</div><div class="detail"><span>Hosting</span><strong>${a.hosting==='managed'?'Managed terminal':'Self-hosted worker'}</strong></div><div class="detail"><span>Risk per trade</span><strong>${fmt(a.risk.risk_pct,1)}% maximum</strong></div></div>${button(a.enabled?'Pause copying':'Start copying','toggle-copy',a.enabled?'pause':'play','full primary',config.demo?'disabled':'')}`:empty('Let’s connect','Add your first MT5 account.','connect','Connect account')}</div></aside></section><section class="panel"><div class="panel-head"><h2>Open positions <small> / ${positions.length}</small></h2><a class="muted" href="#trades">All trades ${icon('chevron')}</a></div>${positionsTable(5)}<div class="table-foot"><span>${config.demo?'Illustrative positions':'Last verified '+when(a?.heartbeat)}</span><span>XAUUSD · MT5</span></div></section><section class="lower-grid"><article class="panel"><div class="panel-head"><h2>Recent activity</h2><a class="muted" href="#activity">View all ${icon('chevron')}</a></div>${recentEvents()}</article><article class="panel"><div class="panel-head"><h2>Your risk boundaries</h2><a class="muted" href="#risk">Edit ${icon('chevron')}</a></div><div class="panel-body"><div class="risk-summary"><div><p>Risk per trade cap</p><strong>${fmt(risk?.risk_pct||0,1)}%</strong></div><div><p>Daily loss stop</p><strong>${fmt(risk?.daily_loss_pct||0,1)}%</strong></div><div><p>Aggregate risk cap</p><strong>${fmt(risk?.total_risk_pct||0,1)}%</strong></div><div><p>Drawdown stop</p><strong>${fmt(risk?.drawdown_pct||0,1)}%</strong></div></div><progress class="meter" value="${Math.min(Math.max(-(s.daily_pnl||0),0)/(s.balance||1)*100,10)}" max="${risk?.daily_loss_pct||3}" aria-label="Realized daily loss relative to configured stop"></progress><small>Realized daily loss · monitoring requires a connected worker</small><p class="section-note">Limits can stop new entries. They do not guarantee a maximum realized loss.</p></div></article></section>`}
function accounts(){return `<div class="page-title"><div><div class="eyebrow">YOUR MT5 CONNECTIONS</div><h1>Trading accounts</h1><p>Keep each account’s execution and risk independent.</p></div>${button('Connect account','connect','plus','primary')}</div><div class="cards">${data.accounts.map(a=>`<article class="panel account-card"><div class="panel-body"><div class="account-overview"><span class="broker-mark">${esc(a.broker[0])}</span><div><strong>${esc(a.name)}</strong><small>${esc(a.broker)} · ${esc(a.login)}</small></div>${badge(a.online?'Online':'Offline',a.online?'':'gray')}</div><div class="balance"><small>ACCOUNT EQUITY · ${esc(a.mode.toUpperCase())}</small>${a.snapshot.equity!==undefined?money(a.snapshot.equity,a.snapshot.currency):'Awaiting verification'}</div><div class="account-details"><div class="detail"><span>Server</span><strong>${esc(a.server)}</strong></div><div class="detail"><span>Instrument</span><strong>${esc(a.symbol)}</strong></div><div class="detail"><span>Hosting</span><strong>${a.hosting==='managed'?'Managed':'Self-hosted'}</strong></div><div class="detail"><span>Copying</span><strong>${a.enabled?'Enabled':'Paused'}</strong></div></div><div class="actions">${button('Open workspace','select-account','arrow','small',`data-account="${a.id}"`)}${button('Worker setup','worker-setup','link','small',`data-account="${a.id}"`)}</div></div></article>`).join('')}<button class="add-card" data-action="connect">${icon('plus')}<strong>Connect another account</strong><p>Exness, PrimeXBT, or another MT5 broker</p></button></div><div class="section-note">Account details alone do not establish a broker connection. Status is verified by the MT5 worker. Broker coverage depends on the actual MT5 account and contract.</div>`}
function analysts(){const a=account();return `<div class="page-title"><div><div class="eyebrow">THE PEOPLE BEHIND THE SIGNALS</div><h1>Analyst directory</h1><p>Follow authorized feeds for the selected account. XAUUSD only.</p></div>${accountSelect()}</div>${data.analysts.length?`<div class="cards">${data.analysts.map(p=>{const followed=a?.follows.some(f=>f.analyst_id===p.id);return `<article class="panel analyst-card"><div class="analyst-art"><span class="avatar">${esc(initials(p.name))}</span><div><h2>${esc(p.name)}</h2><p>XAUUSD · SIGNAL FEED</p></div></div><div class="panel-body"><p class="description">${esc(p.description||'A community analyst feed configured by the operator.')}</p><div class="chip-row">${badge(p.active?'Feed enabled':'Feed paused',p.active?'':'gray')}${followed?badge('Following'):''}</div><div class="actions">${button(followed?'Unfollow analyst':'Follow analyst','follow',followed?'check':'plus',followed?'':'primary',`data-analyst="${p.id}" ${!a||!p.active?'disabled':''}`)}${followed?`<a class="btn" href="#risk">Risk settings</a>`:''}</div></div></article>`}).join('')}</div>`:empty('No feeds configured','An operator can add the authorized Discord trader and channel in the operator console.')}<p class="section-note">Analysts do not have access to account credentials. Unfollowing is blocked while the account has open trades or pending orders so trade protection remains available.</p>`}
function riskPage(){const a=account();if(!a)return empty('Connect an account first','Risk settings belong to individual accounts.','connect','Connect account');const r=a.risk;return `<div class="page-title"><div><div class="eyebrow">BUILT AROUND YOUR BOUNDARIES</div><h1>Risk & execution</h1><p>Set the parameters the worker enforces before every new entry.</p></div>${accountSelect()}</div><div class="form-layout"><form id="risk-form" class="panel"><section class="form-section"><h3>Position sizing</h3><p>Choose your sizing method. The percentage cap applies to every method.</p><div class="form-grid"><div class="field"><label for="risk-scope">Apply settings to</label><select id="risk-scope" name="scope"><option value="">Account defaults</option>${a.follows.map(f=>`<option value="${f.analyst_id}">${esc(data.analysts.find(p=>p.id===f.analyst_id)?.name||'Analyst')} override</option>`).join('')}</select></div><div class="field"><label for="sizing">Sizing method</label><select id="sizing" name="sizing">${[['percent','Equity percentage'],['cash','Account-currency amount'],['fixed','Fixed lot size']].map(([v,l])=>`<option value="${v}" ${r.sizing===v?'selected':''}>${l}</option>`).join('')}</select></div>${fieldsNumber('Risk cap per trade (%)','risk_pct',r.risk_pct,'Maximum stop-loss exposure, across all sizing methods.','.1','.1','2')}${fieldsNumber('Cash risk budget','cash_risk',r.cash_risk,'In account currency units, including cent-account units.','1','.01')}${fieldsNumber('Fixed lot size','fixed_lots',r.fixed_lots,'Used only for fixed-lot sizing.','.01','.01','10')}${fieldsNumber('Maximum lot size','max_lots',r.max_lots,'Upper bound for every entry.','.01','.01','10')}</div></section><section class="form-section"><h3>Account protection</h3><p>These checks stop new entries when a boundary is reached.</p><div class="form-grid">${fieldsNumber('Daily equity loss stop (%)','daily_loss_pct',r.daily_loss_pct,'Measured from the worker’s persisted daily baseline.','.1','.1','10')}${fieldsNumber('Equity drawdown stop (%)','drawdown_pct',r.drawdown_pct,'Measured from the persisted equity high-water mark.','.1','.1','30')}${fieldsNumber('Aggregate open risk cap (%)','total_risk_pct',r.total_risk_pct,'Includes existing positions and pending orders.','.1','.1','10')}${fieldsNumber('Maximum concurrent positions & orders','max_open',r.max_open,'Dedicated hedging accounts are required.','1','1','10')}</div></section><section class="form-section"><h3>Targets & entry filters</h3><p>TP1/TP2 allocations apply to signals using multiple targets. Any remainder is a runner.</p><div class="form-grid">${fieldsNumber('TP1 close (%)','tp1_close_pct',r.tp1_close_pct,'Percentage of the original filled volume.','1','0','100')}${fieldsNumber('TP2 close (%)','tp2_close_pct',r.tp2_close_pct,'TP1 + TP2 must be at most 100%.','1','0','100')}${fieldsNumber('Maximum spread','max_spread',r.max_spread,'Gold price units, not broker points.','.01','.01','20')}${fieldsNumber('Maximum entry distance','max_entry_distance',r.max_entry_distance,'Allowed distance outside the signalled price/range.','.01','.01','20')}<div class="field check"><input type="checkbox" id="be_enabled" name="be_enabled" ${r.be_enabled?'checked':''}><label for="be_enabled">Move SL to actual entry at the BE trigger</label></div><div class="field check"><input type="checkbox" id="respect_manual_stops" name="respect_manual_stops" ${r.respect_manual_stops?'checked':''}><label for="respect_manual_stops">Preserve manual SL/TP adjustments</label></div></div></section><div class="form-actions"><p>Changes apply to future entries.</p><button type="submit" class="btn primary">Save risk settings ${icon('check')}</button></div></form><aside><article class="panel"><div class="panel-head"><h2>Before you save</h2>${icon('risk')}</div><div class="panel-body"><p class="muted">Smaller lots, clearer limits.</p><ol class="checklist"><li>Risk is calculated using the broker’s contract and account currency.</li><li>Lots round down. Trades below the broker minimum are skipped.</li><li>A runner requires the worker to stay online for partial exits.</li><li>Stops can slip. No setting guarantees a maximum loss.</li></ol><p class="section-note">The worker verifies account identity, spread, quote freshness, and available exposure before submission.</p></div></article></aside></div>`}
function trades(){const a=account(),jobs=data.jobs.filter(j=>j.account_id===a?.id);return `<div class="page-title"><div><div class="eyebrow">EVERY COMMAND. EVERY OUTCOME.</div><h1>Trades & orders</h1><p>Broker snapshots and a durable execution trail.</p></div><div class="actions">${accountSelect()}<a class="btn" href="/api/trades/export">${icon('download')}Export CSV</a></div></div><section class="panel"><div class="panel-head"><h2>Open positions</h2>${badge(config.demo?'Sample positions':a?.online?'Verified recently':'Snapshot may be stale',config.demo?'demo':a?.online?'':'gray')}</div>${positionsTable()}</section><section class="panel section-gap"><div class="panel-head"><h2>Pending broker orders</h2></div>${a?.snapshot.orders?.length?`<div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Instrument</th><th>Type</th><th>Entry</th><th>Volume</th><th>Action</th></tr></thead><tbody>${a.snapshot.orders.map(o=>`<tr><td>#${esc(o.ticket)}</td><td>${esc(o.symbol)}</td><td>${esc(o.type)}</td><td>${fmt(o.price_open)}</td><td>${fmt(o.volume)}</td><td>${o.copier?button('Cancel','cancel-order','close','small',`data-ticket="${esc(o.ticket)}"`):'External order'}</td></tr>`).join('')}</tbody></table></div>`:empty('No pending orders','Limit and stop orders appear after broker acceptance.')}</section><section class="panel section-gap"><div class="panel-head"><h2>Today’s closed broker deals</h2><small>Account currency · last 100 reported deals</small></div>${a?.snapshot.deals?.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Deal</th><th>Instrument</th><th>Volume</th><th>Exit price</th><th>Net P&L</th></tr></thead><tbody>${a.snapshot.deals.map(d=>`<tr><td>${when(d.time)}</td><td>#${esc(d.ticket)}</td><td>${esc(d.symbol)}</td><td>${fmt(d.volume)}</td><td>${fmt(d.price)}</td><td class="${d.profit+d.commission+d.swap+d.fee>=0?'positive':'negative'}">${fmt(d.profit+d.commission+d.swap+d.fee)}</td></tr>`).join('')}</tbody></table></div>`:empty('No closed deals reported today','Verified exit deals will appear after your worker reads broker history.')}</section><section class="panel section-gap"><div class="panel-head"><h2>Execution history</h2><input class="search" id="trade-search" aria-label="Filter execution history" placeholder="Filter history…"></div>${jobs.length?`<div class="table-wrap"><table id="history-table"><thead><tr><th>Created</th><th>Instruction</th><th>Reference</th><th>Status</th><th>Broker result</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${when(j.created)}</td><td>${esc(j.payload.side||'')} ${esc(j.payload.action)}</td><td class="mono">${esc(j.id.slice(0,10))}</td><td>${badge(j.state,j.state==='executed'?'':j.state==='uncertain'?'red':'gray')}</td><td>${esc(j.result?.detail||'Awaiting worker response')}</td></tr>`).join('')}</tbody></table></div>`:empty('No execution records yet','Signals and management commands will appear here as they are processed.')}</section>`}
function activity(){return `<div class="page-title"><div><div class="eyebrow">A CLEAR AUDIT TRAIL</div><h1>Workspace activity</h1><p>Account changes, risk updates, signals, and execution outcomes.</p></div>${button('Refresh','refresh','refresh')}</div><section class="panel">${data.events.length?data.events.map(e=>`<article class="notification">${icon(e.kind==='alert'?'alert':e.kind==='security'?'risk':'activity')}<div><strong>${esc(e.kind[0].toUpperCase()+e.kind.slice(1))}</strong><p>${esc(e.detail)}</p><time>${when(e.created)}</time></div></article>`).join(''):empty('No activity yet','Your audit trail starts when you connect your first account.')}</section>`}
function billingPage(){const s=data.subscription;return `<div class="page-title"><div><div class="eyebrow">YOUR WORKSPACE MEMBERSHIP</div><h1>Plan & billing</h1><p>Subscription status is synchronized from verified payment events.</p></div>${button('Manage subscription','billing-portal','billing','',!config.billing_ready||s.status==='inactive'?'disabled':'')}</div>${!config.billing_ready?`<div class="banner">${icon('alert')}<span>${config.demo?'Demo workspace: payments are disabled.':'Billing is not configured. The operator must supply Stripe keys, price IDs, and a webhook endpoint before checkout becomes available.'}</span></div>`:''}<section class="panel"><div class="settings-list"><div class="row"><div><strong>Current membership</strong><p>${config.billing_enabled?'Access follows your verified subscription.':'This installation does not require a paid subscription.'}</p></div>${badge(config.billing_enabled?s.status:'Development access',config.billing_enabled?'':'demo')}</div><div class="row"><div><strong>${esc(s.plan==='free'?'No paid plan':s.plan.toUpperCase())}</strong><p>${s.period_end?'Current period ends '+when(s.period_end):'No billing period is active.'}</p></div><small>Hosted by your community operator</small></div></div></section><section class="cards section-gap">${['basic','pro'].map((p,i)=>`<article class="panel plan ${i?'featured':''}"><span class="plan-tag">${i?'EXTENDED WORKSPACE':'CORE WORKSPACE'}</span><h2>${i?'Pro':'Basic'}</h2><p>Price and renewal terms are shown at checkout.</p><ul><li>MT5 account execution</li><li>XAUUSD analyst feeds</li><li>Risk and trade controls</li><li>Execution history and activity</li></ul>${button('Continue to '+(i?'Pro':'Basic'),'checkout','arrow',i?'primary':'',`data-plan="${p}" ${!config.billing_ready?'disabled':''}`)}</article>`).join('')}</section><p class="section-note">Both plans currently expose the same execution features. Plan-specific quotas are not enabled. Account funds stay with your broker; subscription payments are handled separately by Stripe.</p>`}
function settings(){return `<div class="page-title"><div><div class="eyebrow">YOUR PROFILE & ENVIRONMENT</div><h1>Workspace settings</h1><p>Security, account access, and deployment status.</p></div></div><section class="panel settings-list"><div class="row"><div><strong>${esc(current.name)}</strong><p>${esc(current.email)}</p></div>${badge(current.role==='admin'?'Operator':'Member','gray')}</div><div class="row"><div><strong>Password & sessions</strong><p>Password resets revoke all active browser sessions.</p></div><a class="btn" href="#forgot">Reset password</a></div><div class="row"><div><strong>Execution environment</strong><p>${config.demo?'Demo workspace. Worker claims are disabled.':'Broker execution requires a connected worker.'}</p></div>${badge(config.live_enabled?'Live gate enabled':'Live gate disabled',config.live_enabled?'red':'demo')}</div><div class="row"><div><strong>Managed hosting</strong><p>Accounts are assigned to dedicated Windows terminal slots.</p></div>${badge(config.managed_available?'Supervisor configured':'Not configured',config.managed_available?'':'gray')}</div><div class="row"><div><strong>Account disconnection</strong><p>Disconnect only after the broker verifies no open positions or orders.</p></div>${button('Disconnect selected account','disconnect','link','',!account()?'disabled':'')}</div><div class="row"><div><strong>Service & privacy information</strong><p>Credentials are encrypted at rest; worker tokens can be revoked.</p></div><a class="btn" href="#legal">Read information</a></div></section>`}
function operatorPage(){if(!operator)return empty('Loading operator console','Fetching terminal assignments and unresolved executions.');return `<div class="page-title"><div><div class="eyebrow">COMMUNITY OPERATIONS</div><h1>Operator console</h1><p>Feed configuration, execution recovery, and service visibility.</p></div><div class="actions">${button(data.paused?'Resume platform':'Pause new entries','global-pause','pause',data.paused?'primary':'danger')}${button('Add analyst','add-analyst','plus','primary')}</div></div><div class="operator-grid"><section class="panel"><div class="panel-head"><h2>Terminal assignments</h2><small>${operator.accounts.length} accounts</small></div>${operator.accounts.length?`<div class="table-wrap"><table><thead><tr><th>Account</th><th>Member</th><th>Hosting</th><th>Mode</th><th>Last heartbeat</th></tr></thead><tbody>${operator.accounts.map(a=>`<tr><td>${esc(a.name)} · ${esc(a.login)}</td><td>${esc(a.email)}</td><td>${esc(a.hosting)}</td><td>${badge(a.mode,a.mode==='live'?'red':'demo')}</td><td>${when(a.heartbeat)}</td></tr>`).join('')}</tbody></table></div>`:empty('No terminal assignments','Accounts will appear as members connect.')}</section><section class="panel"><div class="panel-head"><h2>Unresolved executions</h2>${badge(operator.unresolved.length+' require review',operator.unresolved.length?'red':'gray')}</div>${operator.unresolved.length?`<div class="table-wrap"><table><thead><tr><th>Job</th><th>Account</th><th>State</th><th>Action</th></tr></thead><tbody>${operator.unresolved.map(j=>`<tr><td class="mono">${esc(j.id.slice(0,12))}</td><td>${esc(j.account_id.slice(0,12))}</td><td>${badge(j.state,'red')}</td><td>${button('Reconcile','reconcile','check','small',`data-job="${j.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No unresolved executions','Any interrupted submission is held for review; it is never automatically resubmitted.')}</section><section class="panel"><div class="panel-head"><h2>Authorized Discord feeds</h2>${button('Preview or submit signal','signal-tool','plus','small')}</div>${operator.analysts.length?`<div class="table-wrap"><table><thead><tr><th>Analyst</th><th>Guild / channel</th><th>Trader ID</th><th>Status</th><th>Control</th></tr></thead><tbody>${operator.analysts.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.guild_id)} / ${esc(a.channel_id)}</td><td>${esc(a.trader_id)}</td><td>${badge(a.active?'Enabled':'Disabled',a.active?'':'gray')}</td><td>${button(a.active?'Disable':'Enable','analyst-toggle','','small',`data-analyst="${a.id}" data-enabled="${a.active?'false':'true'}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Add your first trader','Configure Discord IDs to begin listening to an authorized signal feed.')}</section></div>`}
function legal(){return `<main class="legal">${brand()}<h1 class="section-gap">Service & privacy information</h1><p>Gold Copier is independent execution software. It does not provide trading advice, custody funds, or guarantee profitable execution. The operator must publish their own complete terms, legal entity details, support contacts, retention policy, and subscription terms before accepting public customers.</p><h2>Credentials & access</h2><p>Browser sessions use HttpOnly cookies. Stored MT5 passwords are encrypted with AES-256-GCM using an operator-managed key. Authorized dedicated workers can decrypt and use credentials through the service. This is encryption at rest, not end-to-end encryption. Only connect an account to an operator you trust.</p><h2>Execution & risk</h2><p>Signals, account snapshots, execution records, and security events are retained in the operator’s database. Workers need uninterrupted terminal access for software-managed exits and breakeven. Disconnections and market gaps can cause missed or delayed actions, and stops can fill beyond their requested prices.</p><h2>Control</h2><p>Pause stops future entries and does not liquidate existing positions. Account disconnection requires a recent empty broker snapshot. Subscription cancellation is managed through the payment provider when configured.</p><a class="btn" href="${current?'#settings':'#home'}">${icon('arrow')}Return to workspace</a></main>`}
const titles={overview:'Overview',accounts:'Accounts',analysts:'Analysts',risk:'Risk & execution',trades:'Trades & orders',activity:'Activity',billing:'Plan & billing',settings:'Settings',operator:'Operator console'};
function shell(body){return `<aside class="sidebar">${brand()}<p class="nav-label">WORKSPACE</p><nav class="nav">${['overview','accounts','analysts','risk','trades','activity'].map(p=>`<a href="#${p}" class="${activePage===p?'active':''}">${icon(p)}${titles[p]}${p==='trades'&&account()?.snapshot.positions?.length?`<span class="pill">${account().snapshot.positions.length}</span>`:''}</a>`).join('')}</nav><p class="nav-label section-gap">MANAGE</p><nav class="nav">${['billing','settings',...(current.role==='admin'?['operator']:[])].map(p=>`<a href="#${p}" class="${activePage===p?'active':''}">${icon(p==='operator'?'risk':p)}${titles[p]}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="nav-card"><strong>A little clarity goes a long way.</strong><p>Set your risk before starting. Your boundaries come first.</p><a href="#risk">Review risk settings →</a></div><div class="user-panel"><span class="avatar">${esc(initials(current.name))}</span><div><strong>${esc(current.name)}</strong><small>${current.role==='admin'?'Community operator':'Member workspace'}</small></div><button data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="mobile-nav" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${titles[activePage]||'Overview'}</strong></div><div class="top-right"><a href="#settings" aria-label="Open profile">Profile</a>${button(publicDemo?'Exit demo':'Sign out','logout','logout','small')}${badge(config.demo?'Demo environment':'MT5 workspace',config.demo?'demo':'gray')}<time>${new Date().toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}</time><a href="#activity" aria-label="Open activity">${icon('bell')}</a></div></header><main class="content">${body}<footer class="footer"><span>Gold Copier · Community execution</span><span>${config.demo?'Seeded sample data · No broker execution':'Risk settings cannot guarantee execution or prevent all losses.'}</span></footer></main></div>`}
async function refresh(render=true){data=publicDemo?(await api('/demo')).dashboard:await api('/dashboard');if(!account())selected=null;if(activePage==='operator'&&current.role==='admin')operator=await api('/operator/status');if(render)renderWorkspace()}
function renderWorkspace(){const views={overview,accounts,analysts,risk:riskPage,trades,activity,billing:billingPage,settings,operator:operatorPage};$('#app').innerHTML=shell((views[activePage]||overview)())}
async function route(){const p=location.hash.slice(1).split('/')[0]||'home';if(current&&!publicDemo&&['home','login','signup','demo'].includes(p)){location.hash='overview';return}if(p==='demo'){try{const r=await api('/demo');publicDemo=true;current=r.user;data=r.dashboard;activePage='overview';renderWorkspace()}catch(e){toast(e.message,true)}return}if(p==='home'){location.hash=publicDemo?'demo':'login';return}if(['how','legal'].includes(p)){if(p==='legal')$('#app').innerHTML=legal();else{$('#app').innerHTML=landing();if(p==='how')$('#how')?.scrollIntoView({behavior:'smooth'})}return}if(['login','signup','forgot','reset'].includes(p)){if(publicDemo)clearSession();$('#app').innerHTML=authPage(p);return}if(!current){location.hash='login';return}activePage=titles[p]?p:'overview';try{await refresh()}catch(e){toast(e.message,true)}}
function connectModal(){modal('Connect an MT5 account',`<div class="steps"><span>01 Account details</span><span>02 Worker setup</span><span>03 Verify & start</span></div><p>Add the broker account first. A worker must verify it before copying can start.</p><div class="form-grid"><div class="field wide"><label for="account-name">Account name</label><input id="account-name" name="name" required minlength="2" maxlength="60" placeholder="My gold account"></div><div class="field"><label for="broker">Broker</label><select id="broker" name="broker"><option>Exness</option><option>PrimeXBT</option><option>Other MT5</option></select></div><div class="field"><label for="mode">Account type</label><select id="mode" name="mode"><option value="demo">Demo account</option>${config.live_enabled?'<option value="live">Live account</option>':''}</select></div><div class="field"><label for="login">MT5 login</label><input id="login" name="login" inputmode="numeric" pattern="[0-9]{3,20}" required placeholder="12345678"></div><div class="field"><label for="server">Broker server</label><input id="server" name="server" required placeholder="Exact MT5 server name"></div><div class="field"><label for="symbol">Gold symbol</label><input id="symbol" name="symbol" value="XAUUSD" pattern="XAUUSD[A-Za-z0-9._-]{0,12}" required><small>Use the broker suffix if needed, such as XAUUSDm.</small></div><div class="field"><label for="hosting">Worker hosting</label><select id="hosting" name="hosting"><option value="self">My Windows worker</option>${config.managed_available&&!config.demo?'<option value="managed">Community managed hosting</option>':''}</select></div><div class="field wide" id="broker-password-field" hidden><label for="broker-password">MT5 trading password</label><input id="broker-password" name="password" type="password" autocomplete="off"><small>Encrypted at rest. The operator’s managed worker can access it to connect MT5.</small></div><div class="field check wide"><input id="consent" name="consent" type="checkbox" required><label for="consent">I own this account and authorize execution according to my settings.</label></div></div>`,'connect-form','Add account')}
function workerModal(id){const a=data.accounts.find(x=>x.id===id);selected=id;localStorage.setItem('gold-account',id);modal('Worker setup',`<p>${a.hosting==='managed'?'This account is queued for the operator’s managed terminal pool. A terminal slot and Windows supervisor must be running.':'Install the project on a Windows machine with a dedicated MT5 terminal. Generate a token below, then follow docs/PLATFORM.md.'}</p><ol class="checklist"><li>Use a dedicated hedging account and terminal installation.</li><li>Run <code>python -m goldcopier.platform_agent</code> with the service URL, worker token, and terminal path.</li><li>Wait for the verified heartbeat, follow an analyst, then start copying.</li></ol><p class="section-note">Generating a new token pauses copying and invalidates the previous worker token. Open positions are not closed.</p>${button('Generate worker token','issue-token','link','primary',`data-account="${a.id}"`)}`)}
function manageModal(ticket,cancel=false){modal(cancel?'Cancel pending order':'Manage position',`<p>Request a broker action for ticket #${esc(ticket)}. The worker will validate ownership and report the actual result. Queued does not mean executed.</p><input type="hidden" name="position" value="${esc(ticket)}"><div class="form-grid"><div class="field wide"><label for="action">Action</label><select id="action" name="action">${cancel?'<option value="cancel">Cancel pending order</option>':'<option value="breakeven">Move SL to actual entry</option><option value="modify">Edit stop loss / take profit</option><option value="partial">Partial close</option><option value="close">Close entire position</option>'}</select></div><div class="field"><label for="command-sl">New stop loss (optional)</label><input id="command-sl" name="sl" type="number" min="0.001" step=".001"></div><div class="field"><label for="command-tp">New take profit (optional)</label><input id="command-tp" name="tp" type="number" min="0.001" step=".001"></div><div class="field"><label for="percent">Partial close (%)</label><input id="percent" name="percent" type="number" min="1" max="100" value="50"></div><div class="field check wide"><input id="confirm-command" type="checkbox" required><label for="confirm-command">I reviewed this action and want the worker to submit it.</label></div></div>`,'command-form','Queue broker action')}
async function action(target){const name=target.dataset.action,a=account();switch(name){case'dismiss-toast':hideToast();break;case'toggle-password':{const input=$('#password'),show=input.type==='password';input.type=show?'text':'password';target.setAttribute('aria-label',show?'Hide password':'Show password');target.setAttribute('aria-pressed',String(show));break}case'dismiss':$('#modal').close();break;case'menu':$('.sidebar')?.classList.toggle('open');break;case'refresh':await refresh();toast('Workspace refreshed');break;case'connect':connectModal();break;case'logout':if(!publicDemo)await post('/auth/logout');clearSession();location.hash='login';await route();break;case'select-account':selected=target.dataset.account;localStorage.setItem('gold-account',selected);location.hash='overview';if(activePage==='overview')renderWorkspace();break;case'worker-setup':workerModal(target.dataset.account);break;case'issue-token':{const r=await post(`/accounts/${target.dataset.account}/token`);modal('Save your worker token',`<p>This token is shown once. Store it in the worker’s environment, never in GitHub or chat.</p><div class="token" id="worker-token">${esc(r.token)}</div><p class="section-note">Copying has been paused. Start it again after the worker verifies its connection.</p>${button('Copy token','copy-token','link','primary')}`);await refresh();break}case'copy-token':await navigator.clipboard.writeText($('#worker-token').textContent);toast('Token copied');break;case'toggle-copy':await post(`/accounts/${a.id}/enabled`,{enabled:!a.enabled});await refresh();toast(a.enabled?'New entries paused':'Copying enabled');break;case'follow':{const id=target.dataset.analyst,enabled=!a.follows.some(f=>f.analyst_id===id);await post(`/accounts/${a.id}/analysts/${id}`,{enabled});await refresh();toast(enabled?'Analyst followed':'Analyst unfollowed');break}case'manage':manageModal(target.dataset.ticket);break;case'cancel-order':manageModal(target.dataset.ticket,true);break;case'chart-period':chartPeriod=target.dataset.period;renderWorkspace();break;case'checkout':{const r=await post('/billing/checkout',{plan:target.dataset.plan});location.assign(r.url);break}case'billing-portal':{const r=await post('/billing/portal');location.assign(r.url);break}case'disconnect':modal('Disconnect selected account',`<p>This removes stored broker credentials and revokes the worker token. The account must be paused with a recent empty broker snapshot.</p>${button('Disconnect account','confirm-disconnect','link','danger')}`);break;case'confirm-disconnect':await api(`/accounts/${a.id}`,{method:'DELETE'});$('#modal').close();await refresh();toast('Credentials removed and token revoked');break;case'global-pause':await post('/operator/pause',{enabled:!data.paused});await refresh();toast('Platform entry state updated');break;case'add-analyst':modal('Add authorized analyst',`<p>The Discord listener accepts only this exact trader, guild, and channel.</p><div class="form-grid"><div class="field wide"><label for="analyst-name">Display name</label><input id="analyst-name" name="name" required minlength="2"></div><div class="field wide"><label for="description">Description</label><input id="description" name="description" maxlength="300"></div>${['guild_id','channel_id','trader_id'].map(k=>`<div class="field"><label for="${k}">${k.replaceAll('_',' ')}</label><input id="${k}" name="${k}" inputmode="numeric" pattern="[0-9]{1,24}" required></div>`).join('')}</div>`,'analyst-form','Add analyst');break;case'analyst-toggle':await post(`/operator/analysts/${target.dataset.analyst}/enabled`,{enabled:target.dataset.enabled==='true'});await refresh();break;case'reconcile':modal('Reconcile execution',`<p>Review the actual MT5 orders, positions, and deal history first. This records your conclusion and never resubmits an order.</p><input type="hidden" name="job" value="${esc(target.dataset.job)}"><div class="field"><label for="resolution">Verified outcome</label><select name="state" id="resolution"><option value="executed">Executed at broker</option><option value="rejected">Not executed at broker</option></select></div><div class="field section-gap"><label for="note">Evidence / reconciliation note</label><textarea name="note" id="note" required minlength="12" maxlength="500" placeholder="Broker order/deal IDs and what you verified"></textarea></div><div class="field check section-gap"><input id="reconcile-confirm" type="checkbox" required><label for="reconcile-confirm">I checked the broker records and stopped any stale worker.</label></div>`,'resolve-form','Record verified outcome');break;case'signal-tool':modal('Signal preview & intake',`<p>Preview parses without trading. Submit queues eligible followers. Use a real source reference and review the instruction before submitting.</p><div class="field"><label for="signal-analyst">Analyst</label><select id="signal-analyst" name="analyst_id" required>${operator.analysts.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field section-gap"><label for="source_id">Source message ID</label><input id="source_id" name="source_id" required placeholder="Discord message ID"></div><div class="field section-gap"><label for="signal-text">Signal</label><textarea id="signal-text" name="text" required>XAUUSD BUY\nENTRY: 2700\nSL: 2695\nTP1: 2710\nTP2: 2720\nBE: 2705</textarea></div><div class="actions section-gap">${button('Preview syntax','preview-signal','check')}</div><pre id="signal-preview" class="token" hidden></pre><div class="field check section-gap"><input id="signal-confirm" type="checkbox" required><label for="signal-confirm">I reviewed this instruction and authorize queueing.</label></div>`,'signal-form','Submit signal');break;case'preview-signal':{const f=$('#signal-form'),v=Object.fromEntries(new FormData(f));const r=await post('/operator/preview',{...v,created:Date.now()/1000});$('#signal-preview').textContent=JSON.stringify(r,null,2);$('#signal-preview').hidden=false;break}}}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action]');if(!t)return;e.preventDefault();if(t.disabled)return;t.disabled=true;try{await action(t)}catch(err){toast(err.message,true)}finally{t.disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='account-select'){selected=e.target.value;localStorage.setItem('gold-account',selected);renderWorkspace()}if(e.target.id==='hosting'){$('#broker-password-field').hidden=e.target.value!=='managed';$('#broker-password').required=e.target.value==='managed'}if(e.target.id==='risk-scope'){const a=account(),override=a.follows.find(f=>f.analyst_id===e.target.value)?.risk;const r=override?JSON.parse(override):a.risk;for(const [k,v] of Object.entries(r)){const f=$(`#risk-form [name="${k}"]`);if(f)f.type==='checkbox'?f.checked=v:f.value=v}}});
document.addEventListener('input',e=>{if(e.target.id==='trade-search'){$$('#history-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}});
const $$=s=>[...document.querySelectorAll(s)];
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),v=Object.fromEntries(new FormData(form));if(button)button.disabled=true;try{switch(form.id){case'login-form':{const r=await post('/auth/login',v);publicDemo=false;current=r.user;csrf=r.csrf;location.hash='overview';break}case'signup-form':await post('/auth/signup',v);toast('Account created. Sign in to continue.');location.hash='login';break;case'forgot-form':await post('/auth/reset-request',v);toast('If the account exists, a reset email will be sent.');break;case'reset-form':await post('/auth/reset',{token:location.hash.split('/')[1],password:v.password});current=null;csrf='';toast('Password reset. Sign in again.');location.hash='login';break;case'connect-form':{const r=await post('/accounts',{...v,consent:true});$('#modal').close();await refresh();workerModal(r.id);break}case'risk-form':{const body={};for(const [k,val]of Object.entries(v)){if(k==='scope')continue;body[k]=k==='sizing'?val:Number(val)}body.be_enabled=form.elements.namedItem('be_enabled').checked;body.respect_manual_stops=form.elements.namedItem('respect_manual_stops').checked;const path=`/accounts/${account().id}/${v.scope?'analysts/'+v.scope+'/risk':'risk'}`;await api(path,{method:'PUT',body});await refresh();toast('Risk settings saved for future entries');break}case'command-form':{const body={action:v.action,position:Number(v.position)};if(v.action==='partial')body.percent=Number(v.percent);if(v.action==='modify'){if(v.sl)body.sl=Number(v.sl);if(v.tp)body.tp=Number(v.tp)}await post(`/accounts/${account().id}/commands`,body);$('#modal').close();await refresh();toast('Command queued. Check execution history for the broker outcome.');break}case'analyst-form':await post('/operator/analysts',v);$('#modal').close();await refresh();toast('Authorized analyst added');break;case'resolve-form':await post(`/operator/jobs/${v.job}/resolve`,{state:v.state,note:v.note});$('#modal').close();await refresh();toast('Reconciliation recorded; no order was resubmitted');break;case'signal-form':{const r=await post('/operator/signals',{...v,created:Date.now()/1000});$('#modal').close();await refresh();toast(r.duplicate?'Duplicate ignored':`Signal accepted; ${r.queued} follower commands queued`);break}}}catch(err){const el=form.querySelector('#auth-error');if(el){el.textContent=err.message;el.hidden=false}else toast(err.message,true)}finally{if(button)button.disabled=false}});
$('#modal').addEventListener('close',placeToast);
window.addEventListener('hashchange',route);
async function init(){try{config=await api('/config');try{const r=await api('/auth/me');current=r.user;csrf=r.csrf}catch(e){if(e.status!==401)throw e}await route()}catch(e){$('#app').innerHTML=`<div class="empty"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><p>Check the API configuration and reload.</p></div>`}}
setInterval(()=>{if(current&&['overview','trades','activity','operator'].includes(activePage)&&!$('#modal').open&&!document.hidden&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))refresh().catch(()=>{})},15000);
init();
